urlParams_s = window.__CM_URL_STATE__ || {}
urlNum_s = function(key, def) {
  const v = urlParams_s[key];
  if (v === undefined) return def;
  const n = Number(v); return Number.isFinite(n) ? n : def;
}
urlBool_s = function(key, def) {
  const v = urlParams_s[key];
  if (v === undefined) return def;
  return v === "1" || v === "true";
}

























